/* Administrative prototypes; role permissions must be enforced by production services. */
'use strict';
AC.adminHeader=(title,desc,action='')=>AC.title(title,desc,action,'Administration / Private workspace');
AC.renders['admin-import']=()=>`${AC.adminHeader('Bring the roster into focus.','Stage a CSV, review its records, and respect suppression before anything is imported.')}<div class="split"><div class="stack"><section class="panel pad"><h2>Import a roster</h2><p class="small muted" style="margin:12px 0 24px">Use fictional records in this prototype. New rows enter as unconfirmed; importing never verifies an alumni identity.</p><div class="field"><label for="roster-file">Roster CSV</label><input type="file" id="roster-file" accept=".csv,text/csv"><small>Required columns: name, email, class_year, city, industry. Quoted fields are supported. Up to 100 sample rows.</small></div><div class="form-actions">${AC.btn('Preview import','preview-import','primary')}${AC.btn('Use sample roster','sample-roster')}${AC.btn('Download CSV template','download-template','quiet')}</div><div id="import-feedback" style="margin-top:24px"></div></section><section class="panel" id="import-preview" hidden></section></div><aside class="right-rail stack"><section class="panel pad"><h2 class="rail-title">Import with care</h2><div class="detail-list"><div class="detail-row"><strong class="small">Suppression comes first</strong><p class="small muted">Removed people are excluded and cannot be re-added.</p></div><div class="detail-row"><strong class="small">Duplicates are skipped</strong><p class="small muted">Email matching is illustrative. Production should use stable identifiers and a reviewable merge.</p></div><div class="detail-row"><strong class="small">Source stays attached</strong><p class="small muted">Imported fields are labeled as roster data and enter the review queue.</p></div></div></section></aside></div>`;
AC.parseCSV=text=>{let rows=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell.trim());cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell.trim());if(row.some(Boolean))rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw new Error('A quoted field is missing its closing quote.');row.push(cell.trim());if(row.some(Boolean))rows.push(row);return rows};
AC.stageImport=text=>{let feedback=document.getElementById('import-feedback'),preview=document.getElementById('import-preview');try{let csv=AC.parseCSV(text),head=csv.shift()?.map(h=>h.toLowerCase().replace(/^\ufeff/,''))||[],required=['name','email','class_year','city','industry'];if(!required.every(k=>head.includes(k)))throw new Error('Add the required headers: '+required.join(', ')+'.');if(csv.length>100)throw new Error('This prototype accepts up to 100 sample rows at a time.');if(!csv.length)throw new Error('The file contains headers but no records.');let existing=new Set(AC.visiblePeople().map(p=>p.email.toLowerCase())),suppression=new Set(AC.state.suppressedEmails||[]),seen=new Set();AC.stagedImport=csv.map((r,i)=>{let obj=Object.fromEntries(head.map((k,n)=>[k,r[n]||''])),reason='Ready';if(!obj.name||!obj.city||!AC.sectors.includes(obj.industry)||!/^\d{4}$/.test(obj.class_year)||!/^[^\s@]+@example\.com$/i.test(obj.email))reason='Needs correction: use a name, valid year, listed industry, city, and example.com email';else if(suppression.has(obj.email.toLowerCase()))reason='Suppressed: previously removed';else if(existing.has(obj.email.toLowerCase())||seen.has(obj.email.toLowerCase()))reason='Duplicate: already in roster';seen.add(obj.email.toLowerCase());return {...obj,row:i+2,reason}});let good=AC.stagedImport.filter(r=>r.reason==='Ready').length;feedback.innerHTML=AC.notice(`${good} ready to import · ${AC.stagedImport.length-good} skipped or need correction. All new records will be unconfirmed.`);preview.hidden=false;preview.innerHTML=`<div class="table-title"><h2>Review before importing</h2><p class="meta" style="margin-top:8px">Source: alumni roster · Identity status: unconfirmed</p></div><div class="table-wrap"><table class="responsive"><thead><tr><th>Record</th><th>Market / year</th><th>Review result</th></tr></thead><tbody>${AC.stagedImport.map(r=>`<tr><td><strong>${AC.esc(r.name)}</strong><p class="meta">${AC.esc(r.email)}</p></td><td>${AC.esc(r.city)} · ${AC.esc(r.class_year)}</td><td>${AC.esc(r.reason)}</td></tr>`).join('')}</tbody></table></div><div class="pad">${AC.btn('Import '+good+' unconfirmed records','commit-import','primary',good?'':'disabled')}</div>`}catch(e){feedback.innerHTML=AC.notice(AC.esc(e.message),'error');preview.hidden=true}};
AC.handlers['preview-import']=async()=>{let f=document.getElementById('roster-file').files[0];if(!f){document.getElementById('import-feedback').innerHTML=AC.notice('Choose a CSV file, or use the sample roster.','error');return}if(f.size>1024*1024){document.getElementById('import-feedback').innerHTML=AC.notice('Use a CSV smaller than 1 MB for this prototype.','error');return}try{AC.stageImport(await f.text())}catch{document.getElementById('import-feedback').innerHTML=AC.notice('The file couldn’t be read. Choose it again or use the sample roster.','error')}};
AC.sampleCSV='name,email,class_year,city,industry\nCasey Monroe,casey.monroe@example.com,2014,Chicago,Finance\nJamie Adler,jamie.adler@example.com,2017,Austin,Technology\nSarah Chen,sarah.chen@example.com,2009,Chicago,Finance';
AC.handlers['sample-roster']=()=>AC.stageImport(AC.sampleCSV);
AC.handlers['download-template']=()=>AC.download('alumni-roster-template.csv',AC.sampleCSV,'text/csv');
AC.handlers['commit-import']=()=>{let records=(AC.stagedImport||[]).filter(r=>r.reason==='Ready');if(!records.length)return;AC.state.imported||=[];records.forEach(r=>{let p={id:'import-'+crypto.randomUUID(),name:r.name,initials:r.name.split(' ').slice(0,2).map(n=>n[0]).join(''),title:'Role not provided',company:'Employer not provided',industry:r.industry,specialty:'Not provided',city:r.city,metro:r.city,year:Number(r.class_year),degree:'Degree not provided',school:'School not provided',confirmed:false,open:[],why:'Imported from a sample alumni roster. Professional details await review.',path:'',relation:'Shared alumni network',history:'Experience not provided',goal:'partners',email:r.email,phone:'Not provided',source:'Alumni roster'};AC.state.imported.push(p);AC.people.push(p)});AC.addAudit('Imported '+records.length+' unconfirmed roster records');AC.stagedImport=[];document.getElementById('import-preview').hidden=true;document.getElementById('import-feedback').innerHTML=AC.notice(`${records.length} unconfirmed records imported. Source retained; records are available for review.`,'success')+`<div class="form-actions">${AC.link('admin-review','Review imported profiles','btn')}</div>`};
AC.reviewPeople=()=>AC.visiblePeople().filter(p=>!p.confirmed&&!AC.state.reviewed?.includes(p.id));
AC.renders['admin-review']=()=>{let ps=AC.reviewPeople();return `${AC.adminHeader('Give uncertain data a human review.','Review source-backed fields before publishing corrections. Content review never marks a person confirmed.')}<section class="panel"><div class="table-title"><div class="section-head" style="margin:0"><h2>Profile review queue</h2><span class="badge-count">${ps.length} awaiting review</span></div><p class="meta" style="margin-top:8px">Low-confidence fields and roster imports · Sample source records</p></div>${AC.stateBlock(ps.length?`<div class="table-wrap"><table class="responsive"><thead><tr><th>Person</th><th>Field needing review</th><th>Source / confidence</th><th>Action</th></tr></thead><tbody>${ps.map(p=>`<tr><td><strong>${p.name}</strong><p class="meta">${p.city} · ${p.year}</p>${AC.badge(p)}</td><td>Current role / employer</td><td><span class="chip">Needs human review</span><p class="meta">${p.source||'Licensed data / public web (sample)'}</p></td><td>${AC.btn('Review profile','review-record','',`data-id="${p.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:AC.empty('The queue is clear','New uncertain records will appear here. A clear queue does not mean all profiles are confirmed.'),'No profiles to review','New low-confidence fields will appear here as imports are processed.')}</section>`};
AC.handlers['review-record']=b=>{let p=AC.byId(b.dataset.id);AC.modal('Review '+AC.esc(p.name),`<p class="small muted">Compare against the cited source before publishing. These source records are fictional.</p><div class="notice" style="margin-top:16px">${AC.icon('file')}<p>Source: ${p.source||'Licensed professional data / public web'} (sample). The live service must attach the exact field citation and retrieval date.</p></div><div style="margin-top:24px">${AC.field('Current title','review-title',p.title)}<div style="margin-top:16px">${AC.field('Employer','review-employer',p.company)}</div><div style="margin-top:16px">${AC.textarea('Review note','review-note','','Record what you checked or corrected.')}</div></div><p class="meta" style="margin-top:16px">The person remains unconfirmed until they claim and verify their identity.</p><div class="form-actions">${AC.btn('Publish reviewed fields','approve-record','primary',`data-id="${p.id}"`)}${AC.btn('Leave in queue','close-dialog')}</div>`,b)};
AC.handlers['approve-record']=b=>{let title=document.getElementById('review-title').value.trim(),company=document.getElementById('review-employer').value.trim(),note=document.getElementById('review-note').value.trim();if(!title||!company||!note){AC.toast('Add a title, employer, and review note.');return}let p=AC.byId(b.dataset.id);p.title=title;p.company=company;AC.state.profileOverrides||={};AC.state.profileOverrides[p.id]={title,company};AC.state.reviewed||=[];AC.state.reviewed.push(p.id);AC.addAudit('Reviewed fields for '+p.name+': '+note);AC.close();AC.render();AC.toast('Fields reviewed. Identity status remains unconfirmed.')};
AC.verificationQueue=()=>[{id:'v1',name:'Morgan Lee',email:'morgan.lee@example.com',year:'2016',evidence:'Degree and roster match (sample)',person:'p8'},...(AC.state.verificationRequested?[{id:'v2',name:'Alex Morgan',email:'alex.morgan@example.com',year:'2008',evidence:'Submitted education details (sample)',person:null}]:[])].filter(v=>!AC.state.verificationDecisions?.[v.id]);
AC.renders['admin-verification']=()=>{let qs=AC.verificationQueue();return `${AC.adminHeader('Protect the shared trust.','Review alumni identity evidence before granting member access.')}<section class="panel"><div class="table-title"><h2>Verification requests</h2><p class="meta" style="margin-top:8px">Decisions are logged. Approval confirms identity; it does not endorse professional claims.</p></div>${AC.stateBlock(qs.length?`<div class="table-wrap"><table class="responsive"><thead><tr><th>Applicant</th><th>Evidence</th><th>Decision</th></tr></thead><tbody>${qs.map(v=>`<tr><td><strong>${v.name}</strong><p class="meta">${v.email} · ${v.year}</p></td><td>${v.evidence}</td><td><div class="od-cluster">${AC.btn('Review request','verify-review','',`data-id="${v.id}"`)}</div></td></tr>`).join('')}</tbody></table></div>`:AC.empty('No pending requests','New requests will appear here when automatic verification needs help.'),'No verification requests','There are no pending applicants in this sample queue.')}</section>`};
AC.handlers['verify-review']=b=>{let v=AC.verificationQueue().find(v=>v.id===b.dataset.id);AC.modal('Verify '+v.name,`<div class="detail-list"><div class="detail-row"><strong>Applicant email</strong><span class="small">${v.email}</span></div><div class="detail-row"><strong>Class year</strong><span class="small">${v.year}</span></div><div class="detail-row"><strong>Evidence</strong><span class="small">${v.evidence}</span></div></div><p class="small muted" style="margin-top:24px">Production approval requires a verified email plus evidence of alumni identity. This prototype demonstrates the decision only.</p><div class="form-actions">${AC.btn('Approve verification','verify-approve','primary',`data-id="${v.id}"`)}${AC.btn('Request more information','verify-more','',`data-id="${v.id}"`)}${AC.btn('Decline request','verify-deny','danger',`data-id="${v.id}"`)}</div>`,b)};
AC.verificationDecision=(b,decision)=>{let v=AC.verificationQueue().find(v=>v.id===b.dataset.id);if(!v)return;AC.state.verificationDecisions||={};AC.state.verificationDecisions[v.id]=decision;if(decision==='Approved'&&v.person){AC.state.confirmedIds||=[];AC.state.confirmedIds.push(v.person);AC.byId(v.person).confirmed=true}AC.addAudit('Verification '+decision.toLowerCase()+': '+v.name);AC.close();AC.render();AC.toast(decision==='More information requested'?'Request for more information recorded; access remains pending.':decision+' · Decision recorded in audit log')};
AC.handlers['verify-approve']=b=>AC.verificationDecision(b,'Approved');AC.handlers['verify-more']=b=>AC.verificationDecision(b,'More information requested');AC.handlers['verify-deny']=b=>AC.verificationDecision(b,'Declined');
AC.renders['admin-removal']=()=>{let ps=AC.visiblePeople().filter(p=>p.id==='p6');return `${AC.adminHeader('Honor a person’s choice to leave.','Public removal is immediate. Review exceptions and track suppression without asking people to create an account.')}<section class="notice" style="margin-bottom:24px">${AC.icon('lock')}<p>Normal public removals bypass this queue and take effect in one step. The queue below illustrates an exception reported to support.</p></section><section class="panel"><div class="table-title"><h2>Removal exceptions</h2></div>${AC.stateBlock(ps.length?`<div class="table-wrap"><table class="responsive"><thead><tr><th>Person</th><th>Request</th><th>Action</th></tr></thead><tbody>${ps.map(p=>`<tr><td><strong>${p.name}</strong><p class="meta">${p.email}</p></td><td>Support-assisted removal<p class="meta">Identity link confirmed (sample)</p></td><td>${AC.btn('Remove & suppress','admin-remove','danger',`data-id="${p.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:AC.empty('No unresolved removals','Completed removals remain suppressed and appear in the audit history.'),'No removal exceptions','Public requests are honored automatically.')}</section><section class="panel pad" style="margin-top:24px"><h2>Suppression register</h2><p class="small muted" style="margin-top:12px">${(AC.state.suppressedEmails||[]).length+(AC.state.publicRemoved?1:0)} sample suppression records. Keep only the minimum identifiers needed to prevent re-import.</p></section>`};
AC.handlers['admin-remove']=b=>{let p=AC.byId(b.dataset.id);AC.modal('Remove '+p.name+'?',`<p class="small muted">This removes the profile from member discovery and adds an import suppression record. It cannot be restored by a normal roster import.</p><div class="form-actions">${AC.btn('Remove and prevent re-import','confirm-admin-remove','danger',`data-id="${p.id}"`)}${AC.btn('Cancel','close-dialog')}</div>`,b)};
AC.handlers['confirm-admin-remove']=b=>{let p=AC.byId(b.dataset.id);AC.state.removed.push(p.id);AC.state.suppressedEmails||=[];AC.state.suppressedEmails.push(p.email.toLowerCase());AC.state.saved=AC.state.saved.filter(id=>id!==p.id);AC.addAudit('Removed and suppressed '+p.name);AC.close();AC.render();AC.toast('Profile removed. Re-import suppression is active.')};
AC.renders['admin-audit']=()=>`${AC.adminHeader('An accountable record of change.','See who changed what, without copying sensitive profile details into the log.')}<section class="panel"><div class="table-title"><h2>Audit history</h2><p class="meta" style="margin-top:8px">Prototype records are browser-local, editable by the browser, and not a production security log.</p></div>${AC.stateBlock(AC.state.audit.length?`<div class="table-wrap"><table class="responsive"><thead><tr><th>Action</th><th>Actor</th><th>Recorded at</th></tr></thead><tbody>${AC.state.audit.map(a=>`<tr><td>${AC.esc(a.action)}</td><td>${AC.esc(a.actor)}</td><td>${AC.esc(a.at)}</td></tr>`).join('')}</tbody></table></div>`:AC.empty('No actions recorded yet','Import a roster or review a request to see its audit record.'),'No audit records','Administrative actions will be recorded here.')}</section>`;
